-- Whether the instance owner can add to an IBM module or create one in SYSIBMADM: it cannot (SQL0551N, SQL0553N). So a
-- routine inside a module whose own row reads OWNERTYPE S is IBM's, and the functions Db2 generated there for the
-- module's types (ORIGIN S, owned by the instance owner that created the database) are admitted by the check.
ALTER MODULE SYSIBMADM.DBMS_LOB ADD TYPE LIBREDB_PROBE_T AS INTEGER ARRAY[];
ALTER MODULE SYSIBMADM.DBMS_LOB PUBLISH FUNCTION LIBREDB_PROBE () RETURNS INTEGER LANGUAGE SQL RETURN 1;
CREATE MODULE SYSIBMADM.LIBREDB_PROBE_M;
SELECT VARCHAR(m.MODULENAME, 14) AS MODULENAME, m.OWNERTYPE AS MODULE_OWNERTYPE, r.ORIGIN, VARCHAR(r.OWNER, 10) AS ROUTINE_OWNER, r.OWNERTYPE AS ROUTINE_OWNERTYPE, COUNT(*) AS N FROM SYSCAT.ROUTINES r JOIN SYSCAT.MODULES m ON m.MODULEID = r.ROUTINEMODULEID WHERE m.MODULESCHEMA = 'SYSIBMADM' AND r.OWNERTYPE <> 'S' GROUP BY m.MODULENAME, m.OWNERTYPE, r.ORIGIN, r.OWNER, r.OWNERTYPE ORDER BY 1;
